package main

import (
	"net/http"
	"net/http/httptest"
	"testing"
)

func TestFixCORSHeaders(t *testing.T) {
	// Create a mock reverseProxy
	rp := &reverseProxy{}

	// Create a mock scope with CORS enabled
	s := &scope{
		user: &user{
			allowCORS: true,
		},
	}

	// Create a test request with Origin header
	req := httptest.NewRequest("GET", "/", nil)
	req.Header.Set("Origin", "http://example.com")

	// Create a response recorder
	rw := httptest.NewRecorder()

	// Call FixCORSHeaders when no existing CORS headers
	rp.FixCORSHeaders(s, rw, req)

	// Check that the header was set correctly
	if got := rw.Header().Get("Access-Control-Allow-Origin"); got != "http://example.com" {
		t.Errorf("Expected Access-Control-Allow-Origin to be 'http://example.com', got '%s'", got)
	}

	// Reset the response recorder
	rw = httptest.NewRecorder()

	// Set an existing CORS header
	rw.Header().Set("Access-Control-Allow-Origin", "http://existing.com")

	// Call FixCORSHeaders when CORS header already exists
	rp.FixCORSHeaders(s, rw, req)

	// Check that the existing header was preserved
	if got := rw.Header().Get("Access-Control-Allow-Origin"); got != "http://existing.com" {
		t.Errorf("Expected Access-Control-Allow-Origin to be preserved as 'http://existing.com', got '%s'", got)
	}

	// Test with no Origin header in request
	reqNoOrigin := httptest.NewRequest("GET", "/", nil)
	rwNoOrigin := httptest.NewRecorder()
	rp.FixCORSHeaders(s, rwNoOrigin, reqNoOrigin)

